"""Statevector simulation for the supported OpenQASM 2.0 subset.

Bit order convention: the statevector index is little-endian. Qubit `q[0]` is
the least significant bit of the basis-state index, so `q[0]=1, q[1]=0` is
index `1`. Basis labels printed by the public API are **big-endian** (most
significant qubit first), which is the conventional OpenQASM readout order:
index `1` of a two-qubit register is printed as `01`.
"""

from __future__ import annotations

import cmath
import math
from typing import Any

from .errors import ValidationError
from .qasm import Circuit, Operation

TOLERANCE = 1e-9
ROUND_DIGITS = 12

_SQRT_HALF = math.sqrt(0.5)


def _rotation(imaginary_sine: bool, angle: float) -> complex:
    """`-i sin(angle)` for `rx`, `sin(angle)` for `ry`."""

    sine = math.sin(angle)
    return complex(0.0, -sine) if imaginary_sine else complex(sine, 0.0)


def initial_state(qubits: int) -> list[complex]:
    state = [0j] * (1 << qubits)
    state[0] = 1 + 0j
    return state


def apply_operation(state: list[complex], qubits: int, operation: Operation) -> None:
    """Apply one gate to `state` in place. `qubits` is the register width."""

    if operation.name == "measure":
        return
    if operation.name in ("cx", "cz"):
        _apply_controlled(state, operation.targets[0], operation.targets[1], operation.name)
        return
    _apply_single_qubit(state, operation, qubits)


def _apply_single_qubit(state: list[complex], operation: Operation, qubits: int) -> None:
    target = operation.targets[0]
    if target >= qubits:  # pragma: no cover - the parser rejects out-of-range qubits
        raise ValidationError(f"qubit {target} is out of range for a {qubits}-qubit circuit")
    mask = 1 << target
    angle = operation.angle
    name = operation.name
    for index in range(len(state)):
        if index & mask:
            continue
        low = state[index]
        high = state[index | mask]
        if name == "h":
            state[index] = (low + high) * _SQRT_HALF
            state[index | mask] = (low - high) * _SQRT_HALF
        elif name == "x":
            state[index], state[index | mask] = high, low
        elif name == "y":
            state[index] = -1j * high
            state[index | mask] = 1j * low
        elif name == "z":
            state[index | mask] = -high
        elif name == "s":
            state[index | mask] = 1j * high
        elif name == "t":
            state[index | mask] = cmath.exp(1j * math.pi / 4) * high
        elif name == "rx":
            cosine = math.cos(angle / 2)
            sine = _rotation(True, angle / 2)
            state[index] = cosine * low + sine * high
            state[index | mask] = sine * low + cosine * high
        elif name == "ry":
            cosine = math.cos(angle / 2)
            sine = _rotation(False, angle / 2)
            state[index] = cosine * low - sine * high
            state[index | mask] = sine * low + cosine * high
        elif name == "rz":
            state[index] = cmath.exp(-1j * angle / 2) * low
            state[index | mask] = cmath.exp(1j * angle / 2) * high
        else:  # pragma: no cover - the parser rejects unknown gates first
            raise ValidationError(f"unsupported gate {name!r}")


def _apply_controlled(state: list[complex], control: int, target: int, name: str) -> None:
    control_mask = 1 << control
    target_mask = 1 << target
    for index in range(len(state)):
        if not index & control_mask or index & target_mask:
            continue
        if name == "cx":
            state[index], state[index | target_mask] = (
                state[index | target_mask],
                state[index],
            )
        else:  # cz
            state[index | target_mask] = -state[index | target_mask]


def simulate(circuit: Circuit) -> list[complex]:
    state = initial_state(circuit.qubits)
    for operation in circuit.operations:
        apply_operation(state, circuit.qubits, operation)
    return state


def norm_squared(state: list[complex]) -> float:
    return sum(abs(amplitude) ** 2 for amplitude in state)


def assert_normalized(state: list[complex]) -> float:
    """Return the normalisation defect, raising when it exceeds the tolerance."""

    defect = abs(norm_squared(state) - 1.0)
    if defect >= TOLERANCE:
        raise ValidationError(
            f"statevector is not normalised: |sum of |alpha|^2 minus 1| = {defect:.3e}"
        )
    return defect


def basis_label(index: int, qubits: int) -> str:
    """Big-endian bit label: qubit `qubits - 1` is the leftmost character."""

    return format(index, f"0{qubits}b")


def clean(value: float) -> float:
    rounded = round(value, ROUND_DIGITS)
    return 0.0 if rounded == 0 else rounded


def clean_complex(value: complex) -> dict[str, float]:
    real = clean(value.real)
    imaginary = clean(value.imag)
    if imaginary == 0:
        imaginary = 0.0
    return {"real": real, "imag": imaginary}


def probabilities(state: list[complex]) -> list[float]:
    return [abs(amplitude) ** 2 for amplitude in state]


def nonzero_amplitudes(circuit: Circuit, state: list[complex]) -> list[dict[str, Any]]:
    """Amplitude entries whose probability is above the reporting threshold."""

    entries: list[dict[str, Any]] = []
    for index, amplitude in enumerate(state):
        probability = abs(amplitude) ** 2
        if probability < TOLERANCE:
            continue
        entries.append(
            {
                "index": index,
                "basis": basis_label(index, circuit.qubits),
                "amplitude": clean_complex(amplitude),
                "probability": clean(probability),
            }
        )
    return entries


def distribution(circuit: Circuit, state: list[complex]) -> dict[str, float]:
    """Every basis state with its probability, keyed by big-endian label."""

    return {
        basis_label(index, circuit.qubits): clean(probability)
        for index, probability in enumerate(probabilities(state))
    }


class Sampler:
    """Deterministic measurement sampling driven by an explicit seed.

    The generator is a splitmix64 stream: it depends only on the seed and the
    number of draws, so the same seed always yields the same counts.
    """

    MASK = (1 << 64) - 1

    def __init__(self, seed: int):
        self.seed = seed & self.MASK
        self.state = self.seed
        self.draws = 0

    def _next(self) -> float:
        self.state = (self.state + 0x9E3779B97F4A7C15) & self.MASK
        value = self.state
        value = ((value ^ (value >> 30)) * 0xBF58476D1CE4E5B9) & self.MASK
        value = ((value ^ (value >> 27)) * 0x94D049BB133111EB) & self.MASK
        value ^= value >> 31
        self.draws += 1
        return (value >> 11) / float(1 << 53)

    def sample(self, weights: list[float], shots: int, qubits: int) -> dict[str, int]:
        """Draw `shots` basis labels with probability proportional to `weights`."""

        cumulative: list[float] = []
        running = 0.0
        for weight in weights:
            running += weight
            cumulative.append(running)
        total = running
        counts: dict[str, int] = {}
        for _ in range(shots):
            threshold = self._next() * total
            index = _locate(cumulative, threshold)
            label = basis_label(index, qubits)
            counts[label] = counts.get(label, 0) + 1
        return counts


def _locate(cumulative: list[float], threshold: float) -> int:
    low = 0
    high = len(cumulative) - 1
    while low < high:
        middle = (low + high) // 2
        if cumulative[middle] <= threshold:
            low = middle + 1
        else:
            high = middle
    return low

from __future__ import annotations

import hashlib
from typing import Any, Callable

from .errors import ConflictError, NotFoundError, ValidationError
from .model import CircuitRequest, SimulationRequest
from .qasm import Circuit, identifier, parse_circuit
from .simulator import (
    Sampler,
    assert_normalized,
    distribution,
    nonzero_amplitudes,
    probabilities,
    simulate,
)
from .store import Store


def _require_key(key: str | None) -> str:
    if not key or not key.strip():
        raise ValidationError("Idempotency-Key header is required")
    if len(key) > 200:
        raise ValidationError("Idempotency-Key must be at most 200 characters")
    return key


class QubitLane:
    """Circuits are immutable; every simulation is an append-only job."""

    def __init__(self, database: str = ":memory:"):
        self.store = Store(database)

    # -- circuits ---------------------------------------------------------

    def create_circuit(self, raw: Any, key: str | None) -> dict[str, Any]:
        _require_key(key)
        request = CircuitRequest.parse(raw)
        circuit = parse_circuit(request.qasm, request.id)
        document = circuit.as_dict()

        def create() -> dict[str, Any]:
            row = self.store.connection.execute(
                "SELECT document FROM circuits WHERE id = ?", (circuit.id,)
            ).fetchone()
            if row:
                stored = self.store.decode(row["document"])
                if stored["qasm"] == circuit.qasm:
                    return stored
                raise ConflictError(f"circuit {circuit.id} already exists with different qasm")
            self.store.connection.execute(
                "INSERT INTO circuits(id, document) VALUES (?, ?)",
                (circuit.id, self.store.encode(document)),
            )
            return document

        return self._idempotent(key, f"create-circuit:{circuit.id}", create)

    def get_circuit(self, circuit_id: str) -> dict[str, Any]:
        row = self.store.connection.execute(
            "SELECT document FROM circuits WHERE id = ?", (circuit_id,)
        ).fetchone()
        if not row:
            raise NotFoundError(f"circuit {circuit_id} was not found")
        return self.store.decode(row["document"])

    def _load(self, circuit_id: str) -> Circuit:
        document = self.get_circuit(circuit_id)
        return parse_circuit(document["qasm"], document["id"])

    # -- simulation -------------------------------------------------------

    def simulate(self, circuit_id: str, raw: Any, key: str | None) -> dict[str, Any]:
        _require_key(key)
        identifier(circuit_id, "circuit id")
        request = SimulationRequest.parse(raw)
        self.get_circuit(circuit_id)

        job_id = self._job_id(circuit_id, request.shots, request.seed)

        def run() -> dict[str, Any]:
            existing = self.store.connection.execute(
                "SELECT document FROM jobs WHERE id = ?", (job_id,)
            ).fetchone()
            if existing:
                return self.store.decode(existing["document"])
            job = self._execute(circuit_id, job_id, request)
            self.store.connection.execute(
                "INSERT INTO jobs(id, circuit_id, document) VALUES (?, ?, ?)",
                (job_id, circuit_id, self.store.encode(job)),
            )
            return job

        return self._idempotent(key, f"simulate:{job_id}", run)

    def get_statevector(self, circuit_id: str) -> dict[str, Any]:
        identifier(circuit_id, "circuit id")
        circuit = self._load(circuit_id)
        state = simulate(circuit)
        defect = assert_normalized(state)
        return {
            "circuit_id": circuit.id,
            "qubits": circuit.qubits,
            "bit_order": "little_endian",
            "normalization_error": defect,
            "amplitudes": nonzero_amplitudes(circuit, state),
        }

    def get_job(self, job_id: str) -> dict[str, Any]:
        identifier(job_id, "job id")
        row = self.store.connection.execute(
            "SELECT document FROM jobs WHERE id = ?", (job_id,)
        ).fetchone()
        if not row:
            raise NotFoundError(f"job {job_id} was not found")
        return self.store.decode(row["document"])

    # -- internals --------------------------------------------------------

    def _execute(self, circuit_id: str, job_id: str, request: SimulationRequest) -> dict[str, Any]:
        circuit = self._load(circuit_id)
        state = simulate(circuit)
        defect = assert_normalized(state)
        weights = probabilities(state)
        sampler = Sampler(request.seed)
        raw_counts = sampler.sample(weights, request.shots, circuit.qubits)
        counts = {self._measured_key(circuit, label): value for label, value in raw_counts.items()}
        ordered = {key: counts[key] for key in sorted(counts)}
        return {
            "id": job_id,
            "circuit_id": circuit.id,
            "state": "completed",
            "shots": request.shots,
            "seed": request.seed,
            "qubits": circuit.qubits,
            "bit_order": "little_endian",
            "normalization_error": defect,
            "probabilities": distribution(circuit, state),
            "counts": ordered,
            "measured_bits": self._measured_bit_count(circuit),
            "created_at": self.store.now(),
        }

    @staticmethod
    def _measured_bit_count(circuit: Circuit) -> int:
        if not circuit.measurements:
            return circuit.qubits
        return max(clbit for _, clbit in circuit.measurements) + 1

    @staticmethod
    def _job_id(circuit_id: str, shots: int, seed: int) -> str:
        raw = f"{circuit_id}|{shots}|{seed}".encode("utf-8")
        return f"j-{hashlib.sha256(raw).hexdigest()[:16]}"

    @staticmethod
    def _measured_key(circuit: Circuit, label: str) -> str:
        """Project a big-endian basis label onto the measured classical bits.

        `label` is big-endian, so character `i` holds qubit `qubits - 1 - i`.
        The result is big-endian as well: character `i` holds classical bit
        `width - 1 - i`. A classical bit that no `measure` statement wrote
        stays `0`.
        """

        if not circuit.measurements:
            return label
        width = QubitLane._measured_bit_count(circuit)
        bits = ["0"] * width
        for qubit, clbit in circuit.measurements:
            bits[clbit] = label[circuit.qubits - 1 - qubit]
        return "".join(reversed(bits))

    def _idempotent(
        self, key: str | None, operation: str, action: Callable[[], dict[str, Any]]
    ) -> dict[str, Any]:
        checked = _require_key(key)
        with self.store.transaction() as connection:
            existing = connection.execute(
                "SELECT operation, response FROM idempotency WHERE key = ?", (checked,)
            ).fetchone()
            if existing:
                if existing["operation"] != operation:
                    raise ConflictError("idempotency key was already used for another operation")
                return self.store.decode(existing["response"])
            response = action()
            connection.execute(
                "INSERT INTO idempotency(key, operation, response) VALUES (?, ?, ?)",
                (checked, operation, self.store.encode(response)),
            )
            return response

from __future__ import annotations

import argparse
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any
from urllib.parse import urlsplit

from .errors import NotFoundError, QubitLaneError, ValidationError
from .service import QubitLane


class Handler(BaseHTTPRequestHandler):
    service: QubitLane

    def log_message(self, format: str, *args: Any) -> None:
        return

    def _json(self, status: int, value: Any) -> None:
        body = json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _body(self) -> Any:
        length_header = self.headers.get("Content-Length")
        if length_header is None:
            return None
        content_type = self.headers.get("Content-Type", "")
        if content_type.split(";", 1)[0].strip().lower() != "application/json":
            raise ValidationError("Content-Type must be application/json")
        try:
            length = int(length_header)
            if length < 0 or length > 1_000_000:
                raise ValueError
            raw = self.rfile.read(length)
            if not raw:
                return None
            return json.loads(raw)
        except (ValueError, json.JSONDecodeError) as error:
            raise ValidationError("request body must be valid JSON") from error

    def _dispatch(self) -> tuple[int, Any]:
        parts = [part for part in urlsplit(self.path).path.split("/") if part]
        if self.command == "GET" and parts == ["health"]:
            return 200, {"status": "ok"}
        if self.command == "POST" and parts == ["circuits"]:
            return 201, self.service.create_circuit(
                self._body(), self.headers.get("Idempotency-Key")
            )
        if (
            self.command == "POST"
            and len(parts) == 3
            and parts[0] == "circuits"
            and parts[2] == "simulate"
        ):
            return 201, self.service.simulate(
                parts[1], self._body(), self.headers.get("Idempotency-Key")
            )
        if (
            self.command == "GET"
            and len(parts) == 3
            and parts[0] == "circuits"
            and parts[2] == "statevector"
        ):
            return 200, self.service.get_statevector(parts[1])
        if self.command == "GET" and len(parts) == 2 and parts[0] == "jobs":
            return 200, self.service.get_job(parts[1])
        raise NotFoundError("route was not found")

    def _handle(self) -> None:
        try:
            status, response = self._dispatch()
            self._json(status, response)
        except QubitLaneError as error:
            self._json(error.status, {"error": {"code": error.code, "message": str(error)}})
        except Exception:
            self._json(500, {"error": {"code": "internal_error", "message": "internal server error"}})

    do_GET = _handle
    do_POST = _handle


def main() -> None:
    parser = argparse.ArgumentParser(description="Run the QubitLane HTTP service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", default=8080, type=int)
    parser.add_argument("--database", default="qubitlane.db")
    arguments = parser.parse_args()
    Handler.service = QubitLane(arguments.database)
    server = ThreadingHTTPServer((arguments.host, arguments.port), Handler)
    print(f"QubitLane listening on http://{arguments.host}:{arguments.port}", flush=True)
    server.serve_forever()


if __name__ == "__main__":
    main()

"""Request models for the QubitLane public contract."""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from typing import Any

from .errors import ValidationError
from .qasm import identifier

MAX_QASM_BYTES = 64 * 1024
MAX_SHOTS = 100_000
MAX_SEED = (1 << 63) - 1

DEFAULT_SHOTS = 1024
DEFAULT_SEED = 0


def _require_object(raw: Any, label: str) -> dict[str, Any]:
    if not isinstance(raw, dict):
        raise ValidationError(f"{label} body must be a JSON object")
    return raw


def _reject_unknown(raw: dict[str, Any], allowed: set[str], label: str) -> None:
    unknown = sorted(set(raw) - allowed)
    if unknown:
        raise ValidationError(f"{label} contains unknown fields: {', '.join(unknown)}")


def _shots(value: Any) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValidationError("shots must be an integer")
    if value < 1 or value > MAX_SHOTS:
        raise ValidationError(f"shots must be between 1 and {MAX_SHOTS}")
    return value


def _seed(value: Any) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValidationError("seed must be an integer")
    if value < 0 or value > MAX_SEED:
        raise ValidationError(f"seed must be between 0 and {MAX_SEED}")
    return value


def content_id(qasm: str) -> str:
    """Deterministic circuit identifier derived from the source text."""

    digest = hashlib.sha256(qasm.encode("utf-8")).hexdigest()[:16]
    return f"c-{digest}"


@dataclass(frozen=True)
class CircuitRequest:
    id: str
    qasm: str

    @classmethod
    def parse(cls, raw: Any) -> "CircuitRequest":
        body = _require_object(raw, "circuit")
        _reject_unknown(body, {"id", "qasm"}, "circuit request")
        if "qasm" not in body:
            raise ValidationError("circuit request must contain a qasm string")
        qasm = body["qasm"]
        if not isinstance(qasm, str) or not qasm.strip():
            raise ValidationError("qasm must be a non-empty string")
        if len(qasm.encode("utf-8")) > MAX_QASM_BYTES:
            raise ValidationError(f"qasm must be at most {MAX_QASM_BYTES} bytes")
        if "id" in body and body["id"] is not None:
            circuit_id = identifier(body["id"], "circuit id")
        else:
            circuit_id = content_id(qasm)
        return cls(id=circuit_id, qasm=qasm)


@dataclass(frozen=True)
class SimulationRequest:
    shots: int
    seed: int

    @classmethod
    def parse(cls, raw: Any) -> "SimulationRequest":
        if raw is None:
            return cls(DEFAULT_SHOTS, DEFAULT_SEED)
        body = _require_object(raw, "simulation")
        _reject_unknown(body, {"shots", "seed"}, "simulation request")
        shots = _shots(body["shots"]) if "shots" in body else DEFAULT_SHOTS
        seed = _seed(body["seed"]) if "seed" in body else DEFAULT_SEED
        return cls(shots, seed)

"""A tiny OpenQASM 2.0 subset parser.

Only the grammar below is accepted. Everything else is a `validation_error`
that names the 1-based source line.

    OPENQASM 2.0;
    include "qelib1.inc";
    qreg name[n];
    creg name[n];
    h|x|y|z|s|t q[i];
    rx|ry|rz(theta) q[i];
    cx|cz q[control], q[target];
    measure q[i] -> c[j];
"""

from __future__ import annotations

import math
import re
from dataclasses import dataclass, field
from typing import Any

from .errors import ParseError, ValidationError

MAX_QUBITS = 16
MAX_CLBITS = 64

SINGLE_QUBIT_GATES = ("h", "x", "y", "z", "s", "t")
PARAMETER_GATES = ("rx", "ry", "rz")
TWO_QUBIT_GATES = ("cx", "cz")
GATES = SINGLE_QUBIT_GATES + PARAMETER_GATES + TWO_QUBIT_GATES

QUBIT = r"q\[(\d+)\]"
CLBIT = r"c\[(\d+)\]"

_HEADER = re.compile(r"^OPENQASM\s+2\.0$")
_INCLUDE = re.compile(r'^include\s+"([^"]*)"$')
_QREG = re.compile(r"^qreg\s+([A-Za-z_][A-Za-z0-9_]*)\s*\[(\d+)\]$")
_CREG = re.compile(r"^creg\s+([A-Za-z_][A-Za-z0-9_]*)\s*\[(\d+)\]$")
_PARAMETER_GATE = re.compile(
    rf"^(rx|ry|rz)\s*\(\s*([^()]*)\s*\)\s+{QUBIT}$"
)
_TWO_QUBIT_GATE = re.compile(rf"^(cx|cz)\s+{QUBIT}\s*,\s*{QUBIT}$")
_SINGLE_QUBIT_GATE = re.compile(rf"^(h|x|y|z|s|t)\s+{QUBIT}$")
_MEASURE = re.compile(rf"^measure\s+{QUBIT}\s*->\s*{CLBIT}$")

_NUMBER = re.compile(r"^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$")
_PI_MULTIPLE = re.compile(r"^([+-]?(?:\d+\.?\d*|\.\d+))\s*\*\s*pi$")
_PI_DIVISOR = re.compile(r"^pi\s*/\s*([+-]?(?:\d+\.?\d*|\.\d+))$")
_PI = re.compile(r"^[+-]?pi$")


@dataclass(frozen=True)
class Operation:
    """One executable statement of the circuit."""

    kind: str  # "gate" or "measure"
    name: str  # gate name, or "measure"
    targets: tuple[int, ...]
    angle: float | None = None
    clbit: int | None = None
    line: int = 0

    def as_dict(self) -> dict[str, Any]:
        payload: dict[str, Any] = {"name": self.name, "targets": list(self.targets)}
        if self.angle is not None:
            payload["angle"] = self.angle
        if self.clbit is not None:
            payload["clbit"] = self.clbit
        return payload


@dataclass(frozen=True)
class Circuit:
    """A parsed circuit: register sizes plus the ordered operation list."""

    id: str
    qubits: int
    clbits: int
    operations: tuple[Operation, ...]
    qasm: str
    source_lines: int
    measurements: tuple[tuple[int, int], ...] = field(default=())

    def as_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "name": self.id,
            "qubits": self.qubits,
            "clbits": self.clbits,
            "bit_order": "little_endian",
            "measurements": [
                {"qubit": qubit, "clbit": clbit} for qubit, clbit in self.measurements
            ],
            "operations": [operation.as_dict() for operation in self.operations],
            "source_lines": self.source_lines,
            "qasm": self.qasm,
        }


def identifier(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value or len(value) > 100:
        raise ValidationError(f"{field} must be a non-empty string of at most 100 characters")
    if any(character.isspace() for character in value):
        raise ValidationError(f"{field} must not contain whitespace")
    return value


def parse_number(text: str, line: int) -> float:
    """Parse a gate angle, allowing `pi`, `pi/2`, `-pi/4`, and `2*pi` forms."""

    candidate = text.strip()
    if not candidate:
        raise ParseError(f"line {line}: angle is missing")
    sign = 1.0
    if candidate.startswith("+"):
        candidate = candidate[1:].strip()
    elif candidate.startswith("-"):
        candidate = candidate[1:].strip()
        sign = -1.0
    if candidate[:1] in ("+", "-"):
        raise ParseError(f"line {line}: angle {text.strip()!r} has a repeated sign")
    if _PI.match(candidate):
        return sign * math.pi
    multiple = _PI_MULTIPLE.match(candidate)
    if multiple:
        return sign * float(multiple.group(1)) * math.pi
    divisor = _PI_DIVISOR.match(candidate)
    if divisor:
        value = float(divisor.group(1))
        if value == 0:
            raise ParseError(f"line {line}: division by zero in angle expression")
        return sign * math.pi / value
    if not _NUMBER.match(candidate):
        raise ParseError(f"line {line}: angle {text.strip()!r} is not a numeric expression")
    value = float(candidate)
    if not math.isfinite(value):
        raise ParseError(f"line {line}: angle must be finite")
    return sign * value


def statements(qasm: str) -> list[tuple[int, str]]:
    """Split source into `(line number, statement)` pairs, stripping comments."""

    if not isinstance(qasm, str) or not qasm.strip():
        raise ValidationError("qasm must be a non-empty string")
    collected: list[tuple[int, str]] = []
    for number, raw in enumerate(qasm.splitlines(), start=1):
        content = raw.split("//", 1)[0]
        for piece in content.split(";"):
            statement = piece.strip()
            if statement:
                collected.append((number, statement))
    return collected


def parse_circuit(qasm: str, circuit_id: str) -> Circuit:
    """Parse OpenQASM 2.0 text into a `Circuit`, or raise a descriptive error."""

    entries = statements(qasm)
    if not entries:
        raise ValidationError("qasm contains no statements")

    first_line, first = entries[0]
    if not _HEADER.match(first):
        raise ParseError(f"line {first_line}: the first statement must be 'OPENQASM 2.0'")

    index = 1
    if index < len(entries):
        line, text = entries[index]
        include = _INCLUDE.match(text)
        if include:
            if include.group(1) != "qelib1.inc":
                raise ParseError(f'line {line}: only include "qelib1.inc" is supported')
            index += 1

    qubits: int | None = None
    clbits: int | None = None
    for line, text in entries[index:]:
        quantum = _QREG.match(text)
        classical = _CREG.match(text)
        if not quantum and not classical:
            break
        name, size_text = (quantum or classical).group(1), (quantum or classical).group(2)
        size = int(size_text)
        if quantum:
            if name != "q":
                raise ParseError(f"line {line}: the quantum register must be named q")
            if qubits is not None:
                raise ParseError(f"line {line}: qreg q is declared more than once")
            if size < 1:
                raise ParseError(f"line {line}: register size must be at least 1")
            if size > MAX_QUBITS:
                raise ParseError(f"line {line}: at most {MAX_QUBITS} qubits are supported")
            qubits = size
        else:
            if name != "c":
                raise ParseError(f"line {line}: the classical register must be named c")
            if clbits is not None:
                raise ParseError(f"line {line}: creg c is declared more than once")
            if size < 1:
                raise ParseError(f"line {line}: register size must be at least 1")
            if size > MAX_CLBITS:
                raise ParseError(f"line {line}: at most {MAX_CLBITS} classical bits are supported")
            clbits = size
        index += 1

    if qubits is None:
        raise ValidationError("qasm must declare a quantum register, for example 'qreg q[2]'")
    clbits = clbits or 0

    operations: list[Operation] = []
    measurements: list[tuple[int, int]] = []
    for line, text in entries[index:]:
        operation = _parse_operation(text, line, qubits, clbits)
        operations.append(operation)
        if operation.kind == "measure" and operation.clbit is not None:
            measurements.append((operation.targets[0], operation.clbit))

    if not operations:
        raise ValidationError("qasm must contain at least one gate or measure statement")
    return Circuit(
        id=circuit_id,
        qubits=qubits,
        clbits=clbits,
        operations=tuple(operations),
        qasm=qasm,
        source_lines=len(qasm.splitlines()),
        measurements=tuple(measurements),
    )


def _parse_operation(text: str, line: int, qubits: int, clbits: int) -> Operation:
    measure = _MEASURE.match(text)
    if measure:
        if clbits == 0:
            raise ParseError(f"line {line}: measure requires a classical register")
        qubit = _checked_bit(int(measure.group(1)), qubits, "qubit", line)
        clbit = _checked_bit(int(measure.group(2)), clbits, "classical bit", line)
        return Operation("measure", "measure", (qubit,), clbit=clbit, line=line)

    parameter = _PARAMETER_GATE.match(text)
    if parameter:
        angle = parse_number(parameter.group(2), line)
        target = _checked_bit(int(parameter.group(3)), qubits, "qubit", line)
        return Operation("gate", parameter.group(1), (target,), angle=angle, line=line)

    two_qubit = _TWO_QUBIT_GATE.match(text)
    if two_qubit:
        control = _checked_bit(int(two_qubit.group(2)), qubits, "qubit", line)
        target = _checked_bit(int(two_qubit.group(3)), qubits, "qubit", line)
        if control == target:
            raise ParseError(
                f"line {line}: {two_qubit.group(1)} requires two distinct qubits"
            )
        return Operation("gate", two_qubit.group(1), (control, target), line=line)

    single = _SINGLE_QUBIT_GATE.match(text)
    if single:
        target = _checked_bit(int(single.group(2)), qubits, "qubit", line)
        return Operation("gate", single.group(1), (target,), line=line)

    name = text.split("(", 1)[0].split(" ", 1)[0].strip()
    if name in GATES:
        raise ParseError(f"line {line}: malformed {name} statement {text!r}")
    raise ParseError(f"line {line}: unsupported statement or gate {text!r}")


def _checked_bit(value: int, size: int, label: str, line: int) -> int:
    if value >= size:
        raise ParseError(
            f"line {line}: {label} index {value} is out of range for a register of size {size}"
        )
    return value

class QubitLaneError(Exception):
    code = "internal_error"
    status = 500


class ValidationError(QubitLaneError):
    code = "validation_error"
    status = 400


class ParseError(ValidationError):
    """A circuit body could not be parsed; reported with a 1-based line number."""

    code = "validation_error"
    status = 400


class NotFoundError(QubitLaneError):
    code = "not_found"
    status = 404


class ConflictError(QubitLaneError):
    code = "conflict"
    status = 409

from __future__ import annotations

import json
import sqlite3
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Iterator


class Store:
    def __init__(self, database: str = ":memory:"):
        if database != ":memory:":
            Path(database).parent.mkdir(parents=True, exist_ok=True)
        self.connection = sqlite3.connect(database, isolation_level=None, check_same_thread=False)
        self.connection.row_factory = sqlite3.Row
        self.connection.execute("PRAGMA journal_mode = WAL")
        self.connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS circuits (
              id TEXT PRIMARY KEY,
              document TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS jobs (
              id TEXT PRIMARY KEY,
              circuit_id TEXT NOT NULL REFERENCES circuits(id),
              document TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS idempotency (
              key TEXT PRIMARY KEY,
              operation TEXT NOT NULL,
              response TEXT NOT NULL
            );
            """
        )

    @contextmanager
    def transaction(self) -> Iterator[sqlite3.Connection]:
        self.connection.execute("BEGIN IMMEDIATE")
        try:
            yield self.connection
        except Exception:
            self.connection.execute("ROLLBACK")
            raise
        else:
            self.connection.execute("COMMIT")

    @staticmethod
    def encode(value: Any) -> str:
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"), sort_keys=True)

    @staticmethod
    def decode(value: str) -> Any:
        return json.loads(value)

    @staticmethod
    def now() -> str:
        return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")

